import json
from pathlib import Path

from client import build_client
from settings import load_settings


HERE = Path(__file__).parent


def test_new_default_and_public_attribute():
    settings = load_settings({})
    assert settings == {"retry_limit": 3}
    client = build_client(settings)
    assert client.retry_limit == 3
    assert not hasattr(client, "max_attempts")


def test_new_environment_variable():
    settings = load_settings({"RETRY_LIMIT": "8", "MAX_ATTEMPTS": "99"})
    assert settings["retry_limit"] == 8
    assert build_client(settings).retry_limit == 8


def test_config_uses_only_new_key():
    cfg = json.loads((HERE / "config.json").read_text())
    assert cfg == {"retry_limit": 3}


def test_docs_and_stub_use_new_name_only():
    for name in ["README.md", "schema.pyi"]:
        text = (HERE / name).read_text()
        assert "retry_limit" in text
        assert "max_attempts" not in text

