from pager import fetch_page


def test_walk_all_pages_without_skips_or_duplicates():
    items = list(range(11))
    cursor = None
    seen = []
    while True:
        page, cursor = fetch_page(items, cursor=cursor, limit=3)
        seen.extend(page)
        if cursor is None:
            break
    assert seen == items


def test_empty_collection_is_terminal():
    assert fetch_page([], limit=5) == ([], None)


def test_limit_larger_than_remaining_is_terminal():
    page, cursor = fetch_page(list("abcd"), cursor="1", limit=20)
    assert page == ["b", "c", "d"]
    assert cursor is None


def test_invalid_limit_still_rejected():
    try:
        fetch_page([1, 2], limit=0)
    except ValueError:
        pass
    else:
        raise AssertionError("limit=0 must raise ValueError")

