import challenge.arch.service.profile_service as service


def _install_repo_spy(monkeypatch):
    calls = []

    def fake_get_profile(user_id):
        calls.append(user_id)
        return {"id": user_id}

    if hasattr(service, "get_profile"):
        monkeypatch.setattr(service, "get_profile", fake_get_profile)
    elif hasattr(service, "profiles"):
        monkeypatch.setattr(service.profiles, "get_profile", fake_get_profile)
    else:
        raise AssertionError("service must obtain profiles through the repository layer")
    return calls


def test_reserved_id_is_denied_even_to_admin_without_repository_access(monkeypatch):
    calls = _install_repo_spy(monkeypatch)
    assert service.fetch_profile("admin", "reserved:root") is None
    assert calls == []


def test_reserved_id_is_denied_to_same_identity_without_repository_access(monkeypatch):
    calls = _install_repo_spy(monkeypatch)
    assert service.fetch_profile("reserved:self", "reserved:self") is None
    assert calls == []


def test_normal_access_semantics_remain():
    assert service.fetch_profile("alice", "alice")["id"] == "alice"
    assert service.fetch_profile("admin", "bob")["id"] == "bob"
    assert service.fetch_profile("alice", "bob") is None
